-- Disposable synthetic ledger; every assertion runs against real commands, roles and native journals.
begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select '00000000-0000-0000-0000-000000000000',('d0511000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'authenticated','authenticated','batch-'||n||'@example.test','',now(),'{"provider":"email","providers":["email"]}','{"display_name":"Batch synthetic"}',now(),now() from generate_series(1,5)n;
create temp table bi(k text primary key,v uuid);create temp table bj(k text primary key,v jsonb);
insert into bi select 'u'||n,p.id from generate_series(1,5)n join public.participants p on p.auth_user_id=('d0511000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid;
create function pg_temp.id(key text)returns uuid language sql as $$select v from bi where k=$1$$;
create function pg_temp.j(key text)returns jsonb language sql as $$select v from bj where k=$1$$;
create function pg_temp.claim(n integer)returns void language plpgsql as $$begin perform set_config('request.jwt.claims',jsonb_build_object('sub','d0511000-0000-4000-8000-'||lpad(n::text,12,'0'),'role','authenticated','is_anonymous',false)::text,true);end$$;
create function pg_temp.cash(n integer,myr bigint,vnd bigint)returns jsonb language sql as $$select jsonb_build_object('participantId',pg_temp.id('u'||n),'cash',jsonb_build_array(jsonb_build_object('currency','MYR','amountMinor',myr::text,'accountId',pg_temp.id('payMYR')),jsonb_build_object('currency','VND','amountMinor',vnd::text,'accountId',pg_temp.id('payVND'))))$$;
create function pg_temp.quote(rows jsonb)returns jsonb language sql as $$select public.quote_trip_settlement_batch(pg_temp.id('trip'),'custom','6000',null,rows)$$;
create function pg_temp.submit(key text,request_key text)returns jsonb language sql as $$select public.submit_trip_settlement_batch((pg_temp.j(key)->>'quoteId')::uuid,pg_temp.id(request_key))$$;
create function pg_temp.child(n integer)returns uuid language sql as $$select (c->>'bundleId')::uuid from jsonb_array_elements(pg_temp.j('receipt')->'children')c where c->>'participantId'=pg_temp.id('u'||n)::text$$;
grant all on bi,bj to authenticated;
set local role authenticated;
select pg_temp.claim(1);
insert into bi values('trip',public.create_space('trip','Synthetic mixed batch',null,null,'MYR')),('othertrip',public.create_space('trip','Other trip',null,null,'MYR'));
insert into bi values('payMYR',(public.create_personal_account(gen_random_uuid(),'Payer MYR','cash','MYR',null,null,false)->>'account_id')::uuid),('payVND',(public.create_personal_account(gen_random_uuid(),'Payer VND','cash','VND',null,null,false)->>'account_id')::uuid),('request',gen_random_uuid()),('badrequest',gen_random_uuid());
reset role;
insert into public.space_members(space_id,participant_id,role)select pg_temp.id('trip'),pg_temp.id('u'||n),'full_access'from generate_series(2,5)n;
set local role authenticated;
select pg_temp.claim(1);
insert into bi select 'bill'||n,(public.create_trip_expense_editor(gen_random_uuid(),pg_temp.id('trip'),jsonb_build_object('expense_scope','space','target_space_id',pg_temp.id('trip'),'participant_ids',array[pg_temp.id('u'||n),pg_temp.id('u1')],'contribution_amounts',array[amount,0],'share_amounts',array[0,amount],'total_minor',amount,'currency_code','MYR','description','Synthetic batch bill','category','Food','occurred_on','2026-11-05'),array[pg_temp.id('u'||n),pg_temp.id('u1')])->>'expense_id')::uuid from(values(2,24560),(3,12040),(4,8525))x(n,amount);
select throws_ok($$select pg_temp.quote(jsonb_build_array(pg_temp.cash(2,15000,573600),pg_temp.cash(3,999999,0)))$$,'P0001','invalid_amount','one overpaid child rejects whole review');
select throws_ok($$select pg_temp.quote(jsonb_build_array(pg_temp.cash(2,0,0)))$$,'P0001','invalid_amount','zero cash rejected');
select throws_ok($$select pg_temp.quote(jsonb_build_array(pg_temp.cash(2,15000,573601)||jsonb_build_object('cash',jsonb_build_array(jsonb_build_object('currency','VND','amountMinor','573600.1','accountId',pg_temp.id('payVND'))))))$$,'P0001','invalid_amount','fractional dong rejected');
select throws_ok($$select pg_temp.quote(jsonb_build_array(pg_temp.cash(2,-1,0)))$$,'P0001','invalid_amount','negative cash rejected');
select throws_ok($$select pg_temp.quote(jsonb_build_array(pg_temp.cash(2,100,0),pg_temp.cash(2,100,0)))$$,'P0001','duplicate_recipient','duplicate person rejected');
select throws_ok($$select public.quote_trip_settlement_batch(pg_temp.id('othertrip'),'custom','6000',null,jsonb_build_array(pg_temp.cash(2,100,0)))$$,'P0001','settlement_participant_denied','cross trip membership denied');
insert into bj values('draft',jsonb_build_array(pg_temp.cash(2,15000,573600),pg_temp.cash(3,12040,0),pg_temp.cash(4,8525,0)));
insert into bj values('quote',pg_temp.quote(pg_temp.j('draft'))),('otherquote',pg_temp.quote(pg_temp.j('draft')));
select is(jsonb_array_length(pg_temp.j('quote')->'children'),3,'all recipients frozen together');
select is((select sum((c->>'cash_minor')::bigint)::bigint from jsonb_array_elements(pg_temp.j('quote')->'children')c),45125::bigint,'reference equivalent 451.25 is separate from actual cash');
select is((select sum((l->>'amountMinor')::bigint)::bigint from jsonb_array_elements(pg_temp.j('quote')->'children')c cross join jsonb_array_elements(c->'cashLegs')l where l->>'currency'='MYR'),35565::bigint,'actual MYR totals 355.65');
select is((select sum((l->>'amountMinor')::bigint)::bigint from jsonb_array_elements(pg_temp.j('quote')->'children')c cross join jsonb_array_elements(c->'cashLegs')l where l->>'currency'='VND'),573600::bigint,'actual VND totals 573600');
select is((select count(*)from public.trip_settlement_batches),0::bigint,'review registers no pending payment');
-- Freeze failure in just one person invalidates all. Deliberate isolated revision bump, not historical cleanup.
reset role;
update public.expenses set version=version+1 where id=pg_temp.id('bill4');
set local role authenticated;
select throws_ok($$select pg_temp.submit('quote','badrequest')$$,'P0001','quote_changed','stale last child rolls back entire registration');
select is((select count(*)from public.trip_settlement_batches),0::bigint,'no partial batch after stale child');
select is((select count(*)from public.personal_money_operations where request_id=pg_temp.id('badrequest')),0::bigint,'failed request receipt also rolls back');
update bj set v=pg_temp.quote(pg_temp.j('draft')) where k in('quote','otherquote');
insert into bj values('receipt',pg_temp.submit('quote','request'));
select is(pg_temp.submit('quote','request'),pg_temp.j('receipt'),'same request returns exact whole batch receipt');
select throws_ok($$select pg_temp.submit('otherquote','request')$$,'P0001','idempotency_conflict','same ID with different frozen contents rejected');
select is((select count(*)from public.trip_settlement_batches),1::bigint,'only one batch');
select is((select count(*)from public.settlement_fx_bundles where status='pending'),3::bigint,'three independent pending children');
select is((select count(*)from public.settlement_payments where fx_cash_only),4::bigint,'four actual native cash legs');
select is((select count(*)from public.personal_account_transactions where kind in('settlement_in','settlement_out')),0::bigint,'pending never posts cash');
select throws_ok($$select pg_temp.quote(jsonb_build_array(pg_temp.cash(2,100,0)))$$,'P0001','pending_pair','batch cannot overlap pending pair');
select throws_ok($$select public.propose_fx_settlement_bundle(gen_random_uuid(),pg_temp.id('trip'),pg_temp.id('u2'),'MYR','custom','{}',24560,pg_temp.id('payMYR'))$$,'P0001','no_outstanding_debt','legacy single cannot double reserve pending batch');
select pg_temp.claim(5);
select is((select count(*)from public.trip_settlement_batches),0::bigint,'third party cannot read batch parent');
select is((select count(*)from public.settlement_fx_bundles),0::bigint,'third party cannot read children');
select throws_ok($$select public.respond_trip_batch_child(pg_temp.child(2),'accepted',1,'{}')$$,'P0001','settlement_participant_denied','third party cannot confirm');
select pg_temp.claim(2);
select is((select count(*)from public.settlement_fx_bundles),1::bigint,'recipient sees only own child');
select ok((select payer_account_id is null and quote::text not like '%'||pg_temp.id('payMYR')::text||'%' and quote::text not like '%'||pg_temp.id('payVND')::text||'%' from public.settlement_fx_bundles where id=pg_temp.child(2)),'payer account IDs never exposed in shared bundle');
select throws_ok($$select public.respond_fx_settlement_bundle(pg_temp.child(2),'accepted',1,pg_temp.id('payMYR'))$$,'P0001','batch_review_required','old scalar confirmation cannot partially post batch child');
insert into bi values('recMYR',(public.create_personal_account(gen_random_uuid(),'Receiver MYR','cash','MYR',null,null,false)->>'account_id')::uuid),('recVND',(public.create_personal_account(gen_random_uuid(),'Receiver VND','cash','VND',null,null,false)->>'account_id')::uuid);
select throws_ok($$select public.respond_trip_batch_child(pg_temp.child(2),'accepted',1,jsonb_build_object('MYR',pg_temp.id('recMYR'),'VND',pg_temp.id('payVND')))$$,'P0001','settlement_cash_account_invalid','wrong second account rolls back first currency posting');
select is((select status from public.settlement_fx_bundles where id=pg_temp.child(2)),'pending','failed confirmation stays pending');
reset role;
select is((select count(*)from public.personal_account_transactions where kind in('settlement_in','settlement_out')),0::bigint,'no first-leg leakage after invalid second account');
set local role authenticated;
select pg_temp.claim(2);
select lives_ok($$select public.respond_trip_batch_child(pg_temp.child(2),'accepted',1,jsonb_build_object('MYR',pg_temp.id('recMYR'),'VND',pg_temp.id('recVND')))$$,'recipient confirms both currencies in one transaction');
select lives_ok($$select public.respond_trip_batch_child(pg_temp.child(2),'accepted',1,'{}')$$,'terminal replay does not post twice');
reset role;
select is(private.space_signed_outstanding(pg_temp.id('trip'),pg_temp.id('u1'),pg_temp.id('u2'),'MYR'),0::bigint,'Full clears exact original currency obligation');
select is(private.space_signed_outstanding(pg_temp.id('trip'),pg_temp.id('u1'),pg_temp.id('u3'),'MYR'),12040::bigint,'B debt untouched when A confirms');
select is((select status from public.settlement_fx_bundles where id=pg_temp.child(3)),'pending','B still pending');
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.id('payMYR')),-15000::bigint,'payer debited actual 150 MYR, not 245.60 equivalent');
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.id('payVND')),-573600::bigint,'payer debited actual VND');
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.id('recMYR')),15000::bigint,'recipient credited actual MYR once');
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.id('recVND')),573600::bigint,'recipient credited actual VND once');
select is((select count(*)from public.personal_account_transactions where kind in('income','expense_funding')),0::bigint,'cash settlement is not spending or ordinary income');
select pg_temp.claim(1);
set local role authenticated;
select lives_ok($$select public.cancel_fx_settlement_bundle(pg_temp.child(3),1)$$,'old cancel releases all pending cash of B');
select pg_temp.claim(4);
select lives_ok($$select public.respond_trip_batch_child(pg_temp.child(4),'declined',1,'{}')$$,'C can decline independently');
reset role;
select is(private.pending_pair_minor(pg_temp.id('trip'),pg_temp.id('u1'),pg_temp.id('u3'),'MYR'),0::bigint,'cancel releases source reservation');
select is(private.space_signed_outstanding(pg_temp.id('trip'),pg_temp.id('u1'),pg_temp.id('u4'),'MYR'),8525::bigint,'decline does not change debt');
set local role authenticated;
select pg_temp.claim(1);
select throws_ok($$select public.reverse_settlement_allocation(gen_random_uuid(),(select a.id from public.settlement_allocations a join public.settlement_payments p on p.id=a.settlement_payment_id where p.fx_cash_only and p.currency='VND' limit 1),1,'one leg')$$,'P0001','fx_bundle_reversal_required','cannot reverse only VND');
select lives_ok($$select public.reverse_fx_settlement_bundle(gen_random_uuid(),pg_temp.child(2),2)$$,'existing whole reversal restores both cash legs and coverage');
reset role;
select is(private.space_signed_outstanding(pg_temp.id('trip'),pg_temp.id('u1'),pg_temp.id('u2'),'MYR'),24560::bigint,'reversal restores original debt');
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.id('payMYR')),0::bigint,'MYR cash reverses to zero');
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.id('payVND')),0::bigint,'VND cash reverses to zero');
select is((select sum(amount_minor)::bigint from public.personal_account_entries where account_id=pg_temp.id('recVND')),0::bigint,'recipient VND reverses to zero');
set local role authenticated;
select pg_temp.claim(1);
insert into bj values('partial',pg_temp.quote(jsonb_build_array(pg_temp.cash(2,15000,300000))));
select is((pg_temp.j('partial')->'children'->0->>'cash_minor')::bigint,20000::bigint,'mixed Partial reference is exactly 200 MYR');
select is((pg_temp.j('partial')->'children'->0->'coverages'->0->>'remaining')::bigint,4560::bigint,'Partial leaves original MYR 45.60');
insert into bj values('vndonly',pg_temp.quote(jsonb_build_array(pg_temp.cash(2,0,1473600))));
select is(jsonb_array_length(pg_temp.j('vndonly')->'children'->0->'cashLegs'),1,'VND-only requires no MYR cash account');
select is((pg_temp.j('vndonly')->'children'->0->'cashLegs'->0->>'currency'),'VND','VND-only cash stays native');
insert into bj values('puremyr',public.quote_trip_settlement_batch(pg_temp.id('trip'),'system',null,null,jsonb_build_array(pg_temp.cash(2,24560,0))));
select is(pg_temp.j('puremyr')->>'snapshotId',null::text,'pure MYR requires no FX snapshot');
reset role;
update private.trip_batch_quotes set expires_at=now()-interval'1 second'where id=(pg_temp.j('partial')->>'quoteId')::uuid;
set local role authenticated;
select throws_ok($$select pg_temp.submit('partial','badrequest')$$,'P0001','quote_expired','expired frozen quote cannot register');
select ok(not has_function_privilege('anon','public.submit_trip_settlement_batch(uuid,uuid)','EXECUTE'),'anonymous cannot submit');
select ok(not has_table_privilege('authenticated','private.trip_batch_cash','SELECT'),'private cash mapping is inaccessible');


-- Real MYR/VND source contra uses exactly the pre-existing proportional native coverage rule.
select pg_temp.claim(1);
insert into bi values('contra',(public.create_trip_expense_editor(gen_random_uuid(),pg_temp.id('trip'),jsonb_build_object('expense_scope','space','target_space_id',pg_temp.id('trip'),'participant_ids',array[pg_temp.id('u1'),pg_temp.id('u2')],'contribution_amounts',array[120000,0],'share_amounts',array[0,120000],'total_minor',120000,'currency_code','VND','description','Native contra source','category','Food','occurred_on','2026-11-05'),array[pg_temp.id('u1'),pg_temp.id('u2')])->>'expense_id')::uuid),('native-request',gen_random_uuid());
insert into bj values('nativepartial',pg_temp.quote(jsonb_build_array(pg_temp.cash(2,10000,600000))));
select is((pg_temp.j('nativepartial')->'children'->0->>'full_net_minor')::bigint,22560::bigint,'native contra is valued once within this person, never across people');
select is((select(c->>'covered')::bigint from jsonb_array_elements(pg_temp.j('nativepartial')->'children'->0->'coverages')c where c->>'currency'='MYR'),21773::bigint,'Partial uses original MYR source ratio');
select is((select(c->>'covered')::bigint from jsonb_array_elements(pg_temp.j('nativepartial')->'children'->0->'coverages')c where c->>'currency'='VND'),106383::bigint,'Partial uses original VND source ratio');
insert into bj values('native-receipt',pg_temp.submit('nativepartial','native-request'));
insert into bi values('native-child',(pg_temp.j('native-receipt')->'children'->0->>'bundleId')::uuid);
select pg_temp.claim(2);
select lives_ok($$select public.respond_trip_batch_child(pg_temp.id('native-child'),'accepted',1,jsonb_build_object('MYR',pg_temp.id('recMYR'),'VND',pg_temp.id('recVND')))$$,'mixed cash confirms against two opposite original currencies');
reset role;
select is(private.space_signed_outstanding(pg_temp.id('trip'),pg_temp.id('u1'),pg_temp.id('u2'),'MYR'),2787::bigint,'remaining is actual MYR source');
select is(private.space_signed_outstanding(pg_temp.id('trip'),pg_temp.id('u2'),pg_temp.id('u1'),'VND'),13617::bigint,'remaining contra is actual VND source');
set local role authenticated;
select pg_temp.claim(1);
select lives_ok($$select public.reverse_fx_settlement_bundle(gen_random_uuid(),pg_temp.id('native-child'),2)$$,'native contra coverage and both cash currencies reverse together');
select throws_ok($$select public.quote_trip_settlement_batch(pg_temp.id('trip'),'custom','100',null,jsonb_build_array(pg_temp.cash(2,100,0)))$$,'P0001','not_net_payer','changed rate cannot turn incoming net into outgoing cash');
reset role;
insert into tabby_fx.snapshots(id,rates,fetched_at)values('d0511000-0000-4000-8000-000000000091','{"VND":{"numerator":"1","denominator":"6000","provider":"Frankfurter","rateDate":"2026-11-05"},"USD":{"numerator":"4","denominator":"1","provider":"Frankfurter","rateDate":"2026-11-05"}}',now()),('d0511000-0000-4000-8000-000000000092','{"VND":{"numerator":"1","denominator":"6200","provider":"Frankfurter","rateDate":"2026-11-05"},"USD":{"numerator":"4","denominator":"1","provider":"Frankfurter","rateDate":"2026-11-05"}}',now());
update tabby_fx.refresh_state set snapshot_id='d0511000-0000-4000-8000-000000000091';
set local role authenticated;
select pg_temp.claim(1);
insert into bj values('system',public.quote_trip_settlement_batch(pg_temp.id('trip'),'system',null,'d0511000-0000-4000-8000-000000000091',jsonb_build_array(pg_temp.cash(2,10000,600000))));
reset role;
update tabby_fx.refresh_state set snapshot_id='d0511000-0000-4000-8000-000000000092';
set local role authenticated;
select throws_ok($$select pg_temp.submit('system','badrequest')$$,'P0001','quote_changed','new system snapshot requires new review, preserving old cash');
insert into bi values('usd',(public.create_trip_expense_editor(gen_random_uuid(),pg_temp.id('trip'),jsonb_build_object('expense_scope','space','target_space_id',pg_temp.id('trip'),'participant_ids',array[pg_temp.id('u2'),pg_temp.id('u1')],'contribution_amounts',array[100,0],'share_amounts',array[0,100],'total_minor',100,'currency_code','USD','description','Other currency source','category','Food','occurred_on','2026-11-05'),array[pg_temp.id('u2'),pg_temp.id('u1')])->>'expense_id')::uuid);
insert into bj values('custom-other',public.quote_trip_settlement_batch(pg_temp.id('trip'),'custom','6000','d0511000-0000-4000-8000-000000000092',jsonb_build_array(pg_temp.cash(2,10000,600000))));
select is(pg_temp.j('custom-other')->'children'->0->'rates'->'USD'->>'source','system','custom VND never overwrites other source currencies');
select is(pg_temp.j('custom-other')->'children'->0->'rates'->'VND'->>'source','custom','custom applies to VND source and cash');
select is((pg_temp.j('custom-other')->'children'->0->>'full_net_minor')::bigint,22960::bigint,'other source uses pinned system USD rate');
select throws_ok($$select public.quote_trip_settlement_batch(pg_temp.id('trip'),'custom','6000',null,jsonb_build_array(pg_temp.cash(2,10000,600000)))$$,'P0001','quote_changed','system-priced other source is pinned even in Custom VND mode');
select * from finish();rollback;
